const { World, setWorldConstructor, setDefaultTimeout } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld extends World {
  constructor(options) {
    super(options);
    this.window = null;
    this.document = null;
  }

  async loadApp() {
    const htmlPath = path.join(ROOT, 'index.html');
    const html = fs.readFileSync(htmlPath, 'utf8');
    this.window = new Window({ url: 'http://localhost/' });
    this.window.document.write(html);
    this.window.document.close();
    this.document = this.window.document;
  }

  async reloadApp() {
    const todos = this._getTodosFromStorage();
    const filter = this._getFilterFromStorage();
    const htmlPath = path.join(ROOT, 'index.html');
    const html = fs.readFileSync(htmlPath, 'utf8');
    this.window = new Window({ url: 'http://localhost/' });
    this.window.document.write(html);
    this.window.document.close();
    this.document = this.window.document;
    // Restore localStorage before app init
    this._setTodosToStorage(todos);
    this._setFilterToStorage(filter);
    // Re-init the app
    this.window.eval('if(typeof App!=="undefined") new App()');
  }

  _getTodosFromStorage() {
    try {
      return JSON.parse(this.window.localStorage.getItem('todos-todomvc') || '[]');
    } catch { return []; }
  }

  _setTodosToStorage(todos) {
    this.window.localStorage.setItem('todos-todomvc', JSON.stringify(todos));
  }

  _getFilterFromStorage() {
    return this.window.localStorage.getItem('filter') || '';
  }

  _setFilterToStorage(filter) {
    if (filter) this.window.localStorage.setItem('filter', filter);
  }

  getTodoItems() {
    return Array.from(this.document.querySelectorAll('.todo-list li'));
  }

  findTodoByTitle(title) {
    return this.getTodoItems().find(li => {
      const label = li.querySelector('label');
      return label && label.textContent === title;
    });
  }
}

setWorldConstructor(AppWorld);
setDefaultTimeout(10000);

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

function addTodoToStorage(world, title, completed = false) {
  const todos = world._getTodosFromStorage();
  todos.push({ id: Date.now() + Math.random(), title, completed });
  world._setTodosToStorage(todos);
}

function seedTodos(world, items) {
  const todos = items.map((item, i) => ({
    id: i + 1,
    title: item.title,
    completed: item.completed || false
  }));
  world._setTodosToStorage(todos);
}

function getInput(world) {
  return world.document.querySelector('.new-todo');
}

function getEditInput(world, li) {
  return li ? li.querySelector('.edit') : world.document.querySelector('.todo-list li.editing .edit');
}

function getToggleForTodo(world, title) {
  const li = world.findTodoByTitle(title);
  return li ? li.querySelector('.toggle') : null;
}

function getDestroyForTodo(world, title) {
  const li = world.findTodoByTitle(title);
  return li ? li.querySelector('.destroy') : null;
}

function fireKeydown(input, keyCode) {
  const event = new input.ownerDocument.defaultView.KeyboardEvent('keydown', {
    keyCode,
    which: keyCode,
    bubbles: true
  });
  input.dispatchEvent(event);
}

function fireInputEvent(input, value) {
  const win = input.ownerDocument.defaultView;
  input.value = value;
  input.dispatchEvent(new win.Event('input', { bubbles: true }));
}

function fireChangeEvent(input) {
  const win = input.ownerDocument.defaultView;
  input.dispatchEvent(new win.Event('change', { bubbles: true }));
  input.dispatchEvent(new win.Event('blur', { bubbles: true }));
}

function clickElement(el) {
  const win = el.ownerDocument.defaultView;
  el.click();
  el.dispatchEvent(new win.Event('change', { bubbles: true }));
}

// ========== Given ==========

Given('the app is loaded with no todos', async function () {
  this._setTodosToStorage([]);
  await this.loadApp();
});

Given('the app is loaded with a todo {string}', async function (title) {
  seedTodos(this, [{ title }]);
  await this.loadApp();
});

Given('the app is loaded with a completed todo {string}', async function (title) {
  seedTodos(this, [{ title, completed: true }]);
  await this.loadApp();
});

Given('the app is loaded with an incomplete todo {string}', async function (title) {
  seedTodos(this, [{ title, completed: false }]);
  await this.loadApp();
});

Given('the app is loaded with an incomplete todo {string} and an incomplete todo {string}', async function (t1, t2) {
  seedTodos(this, [{ title: t1 }, { title: t2 }]);
  await this.loadApp();
});

Given('the app is loaded with a completed todo {string} and a completed todo {string}', async function (t1, t2) {
  seedTodos(this, [{ title: t1, completed: true }, { title: t2, completed: true }]);
  await this.loadApp();
});

Given('the app is loaded with an incomplete todo {string} and a completed todo {string}', async function (t1, t2) {
  seedTodos(this, [{ title: t1, completed: false }, { title: t2, completed: true }]);
  await this.loadApp();
});

Given('the app is loaded with an incomplete todo {string} and a completed todo {string} and a completed todo {string}', async function (t1, t2, t3) {
  seedTodos(this, [
    { title: t1, completed: false },
    { title: t2, completed: true },
    { title: t3, completed: true }
  ]);
  await this.loadApp();
});

Given('the app is loaded with a todo {string} and a todo {string}', async function (t1, t2) {
  seedTodos(this, [{ title: t1 }, { title: t2 }]);
  await this.loadApp();
});

Given('the user clicks the toggle checkbox on the todo {string}', function (title) {
  const toggle = getToggleForTodo(this, title);
  assert(toggle, `Toggle not found for todo "${title}"`);
  clickElement(toggle);
});

Given('the page is reloaded', async function () {
  await this.reloadApp();
});

// ========== When ==========

When('the user types {string} in the new todo input and presses Enter', function (text) {
  const input = getInput(this);
  assert(input, 'New todo input not found');
  fireInputEvent(input, text);
  fireKeydown(input, 13);
});

When('the user types {string} in the edit input and presses Enter', function (text) {
  const input = getEditInput(this);
  assert(input, 'Edit input not found');
  fireInputEvent(input, text);
  fireKeydown(input, 13);
});

When('the user double-clicks the todo {string}', function (title) {
  const li = this.findTodoByTitle(title);
  assert(li, `Todo "${title}" not found`);
  const label = li.querySelector('label');
  assert(label, 'Label not found');
  const dblclick = new this.window.Event('dblclick', { bubbles: true });
  label.dispatchEvent(dblclick);
});

When('the user types {string} in the edit input and blurs', function (text) {
  const input = getEditInput(this);
  assert(input, 'Edit input not found');
  fireInputEvent(input, text);
  fireChangeEvent(input);
});

When('the user clears the edit input and presses Enter', function () {
  const input = getEditInput(this);
  assert(input, 'Edit input not found');
  fireInputEvent(input, '');
  fireKeydown(input, 13);
});

When('the user types {string} in the edit input and presses Escape', function (text) {
  const input = getEditInput(this);
  assert(input, 'Edit input not found');
  fireInputEvent(input, text);
  fireKeydown(input, 27);
});

When('the user clicks the Mark all as complete checkbox', function () {
  const checkbox = this.document.querySelector('#toggle-all');
  assert(checkbox, 'Toggle-all checkbox not found');
  clickElement(checkbox);
});

When('the user clicks the Clear completed button', function () {
  const btn = this.document.querySelector('.clear-completed');
  assert(btn, 'Clear completed button not found');
  clickElement(btn);
});

When('the user navigates to {string}', function (route) {
  const hash = route.startsWith('#') ? route : '#' + route;
  this.window.location.hash = hash;
  this.window.dispatchEvent(new this.window.HashChangeEvent('hashchange'));
});

When('the app is loaded fresh', async function () {
  this._setTodosToStorage([]);
  await this.loadApp();
});

When('the user clicks the destroy button on the todo {string}', function (title) {
  const destroy = getDestroyForTodo(this, title);
  assert(destroy, `Destroy button not found for todo "${title}"`);
  clickElement(destroy);
});

// ========== Then ==========

Then('a todo {string} is displayed in the list', function (title) {
  const li = this.findTodoByTitle(title);
  assert(li, `Todo "${title}" not found in the list`);
});

Then('the new todo input is empty', function () {
  const input = getInput(this);
  assert(input, 'New todo input not found');
  assert.strictEqual(input.value, '', 'New todo input is not empty');
});

Then('the todo counter displays {string}', function (text) {
  const counter = this.document.querySelector('.todo-count');
  assert(counter, 'Todo counter not found');
  assert.strictEqual(counter.textContent.trim(), text.trim());
});

Then('no todos are displayed', function () {
  const items = this.getTodoItems();
  assert.strictEqual(items.length, 0, `Expected 0 todos, got ${items.length}`);
});

Then('the new todo input is focused', function () {
  const input = getInput(this);
  assert(input, 'New todo input not found');
  assert.strictEqual(this.document.activeElement, input);
});

Then('two todos are displayed', function () {
  const items = this.getTodoItems();
  assert.strictEqual(items.length, 2, `Expected 2 todos, got ${items.length}`);
});

Then('the todo {string} is in editing mode', function (title) {
  const li = this.findTodoByTitle(title);
  assert(li, `Todo "${title}" not found`);
  assert(li.classList.contains('editing'), `Todo "${title}" is not in editing mode`);
});

Then('the edit input contains {string}', function (text) {
  const input = getEditInput(this);
  assert(input, 'Edit input not found');
  assert.strictEqual(input.value, text);
});

Then('the edit input is focused', function () {
  const input = getEditInput(this);
  assert(input, 'Edit input not found');
  assert.strictEqual(this.document.activeElement, input);
});

Then('the todo {string} is not in editing mode', function (title) {
  const li = this.findTodoByTitle(title);
  assert(li, `Todo "${title}" not found`);
  assert(!li.classList.contains('editing'), `Todo "${title}" is still in editing mode`);
});

Then('the todo {string} is marked as completed', function (title) {
  const li = this.findTodoByTitle(title);
  assert(li, `Todo "${title}" not found`);
  assert(li.classList.contains('completed'), `Todo "${title}" is not marked as completed`);
});

Then('the todo {string} is not marked as completed', function (title) {
  const li = this.findTodoByTitle(title);
  assert(li, `Todo "${title}" not found`);
  assert(!li.classList.contains('completed'), `Todo "${title}" is still marked as completed`);
});

Then('the Mark all as complete checkbox is checked', function () {
  const checkbox = this.document.querySelector('#toggle-all');
  assert(checkbox, 'Toggle-all checkbox not found');
  assert(checkbox.checked, 'Toggle-all checkbox is not checked');
});

Then('the Mark all as complete checkbox is not checked', function () {
  const checkbox = this.document.querySelector('#toggle-all');
  assert(checkbox, 'Toggle-all checkbox not found');
  assert(!checkbox.checked, 'Toggle-all checkbox is still checked');
});

Then('the Clear completed button is not visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (btn) {
    const style = this.window.getComputedStyle(btn);
    assert.notStrictEqual(style.display, 'none', 'Clear completed button should not be visible');
  }
});

Then('the Clear completed button is visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  assert(btn, 'Clear completed button not found');
  const style = this.window.getComputedStyle(btn);
  assert.notStrictEqual(style.display, 'none', 'Clear completed button is not visible');
});

Then('the main section is not visible', function () {
  const main = this.document.querySelector('.main');
  if (main) {
    const style = this.window.getComputedStyle(main);
    assert.strictEqual(style.display, 'none', 'Main section should be hidden');
  }
});

Then('the footer is not visible', function () {
  const footer = this.document.querySelector('.footer');
  if (footer) {
    const style = this.window.getComputedStyle(footer);
    assert.strictEqual(style.display, 'none', 'Footer should be hidden');
  }
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  assert(main, 'Main section not found');
  const style = this.window.getComputedStyle(main);
  assert.notStrictEqual(style.display, 'none', 'Main section is not visible');
});

Then('the footer is visible', function () {
  const footer = this.document.querySelector('.footer');
  assert(footer, 'Footer not found');
  const style = this.window.getComputedStyle(footer);
  assert.notStrictEqual(style.display, 'none', 'Footer is not visible');
});

Then('the {string} filter link is selected', function (filterName) {
  const links = this.document.querySelectorAll('.filters a');
  let found = false;
  for (const link of links) {
    if (link.textContent === filterName) {
      assert(link.classList.contains('selected'), `Filter "${filterName}" is not selected`);
      found = true;
    } else {
      assert(!link.classList.contains('selected'), `Filter "${link.textContent}" should not be selected`);
    }
  }
  assert(found, `Filter "${filterName}" link not found`);
});

