(function () {
	'use strict';

	var ENTER_KEY = 13;
	var ESCAPE_KEY = 27;
	var STORAGE_KEY = 'todos-todomvc';

	function App() {
		this.todos = this._loadTodos();
		this.currentFilter = this._loadFilter();
		this.newTodoInput = document.querySelector('.new-todo');
		this.todoList = document.querySelector('.todo-list');
		this.toggleAll = document.querySelector('#toggle-all');
		this.mainSection = document.querySelector('.main');
		this.footer = document.querySelector('.footer');
		this.todoCount = document.querySelector('.todo-count');
		this.clearCompletedBtn = document.querySelector('.clear-completed');
		this.filterLinks = document.querySelectorAll('.filters a');

		this._bindEvents();
		this._render();
	}

	App.prototype._loadTodos = function () {
		try {
			return JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
		} catch (e) {
			return [];
		}
	};

	App.prototype._saveTodos = function () {
		localStorage.setItem(STORAGE_KEY, JSON.stringify(this.todos));
	};

	App.prototype._loadFilter = function () {
		var hash = window.location.hash || '#/';
		if (hash === '#/active') return 'active';
		if (hash === '#/completed') return 'completed';
		return 'all';
	};

	App.prototype._saveFilter = function () {
		localStorage.setItem('filter', this.currentFilter);
	};

	App.prototype._bindEvents = function () {
		var self = this;

		this.newTodoInput.addEventListener('keydown', function (e) {
			if (e.keyCode === ENTER_KEY) {
				self._addTodo();
			}
		});

		this.toggleAll.addEventListener('change', function () {
			self._toggleAll(this.checked);
		});

		this.clearCompletedBtn.addEventListener('click', function () {
			self._clearCompleted();
		});

		for (var i = 0; i < this.filterLinks.length; i++) {
			this.filterLinks[i].addEventListener('click', function (e) {
				e.preventDefault();
				var href = this.getAttribute('href');
				window.location.hash = href;
			});
		}

		window.addEventListener('hashchange', function () {
			self.currentFilter = self._loadFilter();
			self._saveFilter();
			self._render();
		});

		this.todoList.addEventListener('change', function (e) {
			if (e.target.classList.contains('toggle')) {
				var li = e.target.closest('li');
				var id = parseInt(li.dataset.id, 10);
				self._toggleTodo(id);
			}
		});

		this.todoList.addEventListener('click', function (e) {
			if (e.target.classList.contains('destroy')) {
				var li = e.target.closest('li');
				var id = parseInt(li.dataset.id, 10);
				self._deleteTodo(id);
			}
		});

		this.todoList.addEventListener('dblclick', function (e) {
			if (e.target.tagName === 'LABEL') {
				var li = e.target.closest('li');
				self._editTodo(li);
			}
		});
	};

	App.prototype._addTodo = function () {
		var title = this.newTodoInput.value.trim();
		if (!title) return;
		this.todos.push({
			id: Date.now(),
			title: title,
			completed: false
		});
		this.newTodoInput.value = '';
		this._saveTodos();
		this._render();
	};

	App.prototype._toggleTodo = function (id) {
		var todo = this.todos.find(function (t) { return t.id === id; });
		if (todo) {
			todo.completed = !todo.completed;
			this._saveTodos();
			this._render();
		}
	};

	App.prototype._deleteTodo = function (id) {
		this.todos = this.todos.filter(function (t) { return t.id !== id; });
		this._saveTodos();
		this._render();
	};

	App.prototype._toggleAll = function (checked) {
		this.todos.forEach(function (todo) {
			todo.completed = checked;
		});
		this._saveTodos();
		this._render();
	};

	App.prototype._clearCompleted = function () {
		this.todos = this.todos.filter(function (t) { return !t.completed; });
		this._saveTodos();
		this._render();
	};

	App.prototype._editTodo = function (li) {
		li.classList.add('editing');
		var editInput = li.querySelector('.edit');
		editInput.value = li.querySelector('label').textContent;
		editInput.focus();

		var self = this;
		var id = parseInt(li.dataset.id, 10);

		function handleEditKeydown(e) {
			if (e.keyCode === ENTER_KEY) {
				saveEdit();
			} else if (e.keyCode === ESCAPE_KEY) {
				cancelEdit();
			}
		}

		function handleEditBlur() {
			saveEdit();
		}

		function saveEdit() {
			editInput.removeEventListener('keydown', handleEditKeydown);
			editInput.removeEventListener('blur', handleEditBlur);
			var newTitle = editInput.value.trim();
			if (newTitle) {
				var todo = self.todos.find(function (t) { return t.id === id; });
				if (todo) {
					todo.title = newTitle;
					self._saveTodos();
				}
			} else {
				self._deleteTodo(id);
				return;
			}
			self._render();
		}

		function cancelEdit() {
			editInput.removeEventListener('keydown', handleEditKeydown);
			editInput.removeEventListener('blur', handleEditBlur);
			self._render();
		}

		editInput.addEventListener('keydown', handleEditKeydown);
		editInput.addEventListener('blur', handleEditBlur);
	};

	App.prototype._render = function () {
		var filtered = this.todos.filter(function (todo) {
			if (this.currentFilter === 'active') return !todo.completed;
			if (this.currentFilter === 'completed') return todo.completed;
			return true;
		}.bind(this));

		this.todoList.innerHTML = '';
		filtered.forEach(function (todo) {
			var li = document.createElement('li');
			li.dataset.id = todo.id;
			if (todo.completed) li.classList.add('completed');

			li.innerHTML =
				'<div class="view">' +
					'<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
					'<label>' + todo.title + '</label>' +
					'<button class="destroy"></button>' +
				'</div>' +
				'<input class="edit" value="' + todo.title + '">';

			this.todoList.appendChild(li);
		}.bind(this));

		var activeCount = this.todos.filter(function (t) { return !t.completed; }).length;
		var completedCount = this.todos.filter(function (t) { return t.completed; }).length;
		var totalCount = this.todos.length;

		this.todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' +
			(activeCount === 1 ? 'item' : 'items') + ' left';

		this.mainSection.style.display = totalCount === 0 ? 'none' : '';
		this.footer.style.display = totalCount === 0 ? 'none' : '';

		this.clearCompletedBtn.style.display = completedCount === 0 ? 'none' : '';

		this.toggleAll.checked = totalCount > 0 && activeCount === 0;

		for (var i = 0; i < this.filterLinks.length; i++) {
			var link = this.filterLinks[i];
			var href = link.getAttribute('href');
			if ((this.currentFilter === 'all' && href === '#/') ||
				(this.currentFilter === 'active' && href === '#/active') ||
				(this.currentFilter === 'completed' && href === '#/completed')) {
				link.classList.add('selected');
			} else {
				link.classList.remove('selected');
