const { World, setWorldConstructor, setDefaultTimeout } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld extends World {
  constructor(options) {
    super(options);
    this.window = null;
    this.document = null;
  }

  _ensureWindow() {
    if (!this.window) {
      this.window = new Window({ url: 'http://localhost/' });
      this.document = this.window.document;
    }
  }

  async loadApp() {
    this._ensureWindow();
    const htmlPath = path.join(ROOT, 'index.html');
    const html = fs.readFileSync(htmlPath, 'utf8');
    this.window.document.write(html);
    this.window.document.close();
    this.document = this.window.document;
  }

  async reloadApp() {
    const todos = this._getTodosFromStorage();
    const filter = this._getFilterFromStorage();
    this._ensureWindow();
    const htmlPath = path.join(ROOT, 'index.html');
    const html = fs.readFileSync(htmlPath, 'utf8');
    this.window.document.write(html);
    this.window.document.close();
    this.document = this.window.document;
    this._setTodosToStorage(todos);
    this._setFilterToStorage(filter);
    this.window.eval('if(typeof App!=="undefined") new App()');
  }

  _getTodosFromStorage() {
    this._ensureWindow();
    try {
      return JSON.parse(this.window.localStorage.getItem('todos-todomvc') || '[]');
    } catch { return []; }
  }

  _setTodosToStorage(todos) {
    this._ensureWindow();
    this.window.localStorage.setItem('todos-todomvc', JSON.stringify(todos));
  }

  _getFilterFromStorage() {
    this._ensureWindow();
    return this.window.localStorage.getItem('filter') || '';
  }

  _setFilterToStorage(filter) {
    this._ensureWindow();
    if (filter) this.window.localStorage.setItem('filter', filter);
  }

  getTodoItems() {
    return Array.from(this.document.querySelectorAll('.todo-list li'));
  }

  findTodoByTitle(title) {
    return this.getTodoItems().find(li => {
      const label = li.querySelector('label');
      return label && label.textContent === title;
    });
  }
}

setWorldConstructor(AppWorld);
setDefaultTimeout(10000);

